  lemma SearchReturnsAccurateInfo(query: string, m: Model)
    ensures 
      (query != "" ==> 
        (query in Apply(m, Search(query)) ==>
          Apply(m, Search(query))[query].seeders >= 0 && 
          Apply(m, Search(query))[query].leechers >= 0 && 
          Apply(m, Search(query))[query].size >= 0 &&
